import { Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import * as ButtonGroup from "../../ui/button-group";
import * as Button from "../../ui/shadcn-button";

// MODEL

export const Model = S.Struct({});
export type Model = typeof Model.Type;

// MESSAGE

export const Message = S.Never;
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{}, []];

// UPDATE

export const update = (
  model: Model,
  _message: Message
): readonly [Model, readonly Command.Command<Message>[]] => [model, []];

// VIEW

const shadcnButton = (label: string, className: string): Html => {
  const h = html<Message>();

  return Button.view<Message>({
    toView: (attributes) =>
      h.button([...attributes.button, h.Class(className)], [label]),
  });
};

export const view = Submodel.defineView<Model, Message>(
  (): Html =>
    ButtonGroup.view<Message>({
      ariaLabel: "Report actions",
      children: [
        ButtonGroup.itemView<Message>({
          children: [
            shadcnButton("Archive Report", Button.shadcnButtonClassName),
          ],
        }),
        ButtonGroup.itemView<Message>({
          children: [
            shadcnButton("Snooze", Button.shadcnSecondaryButtonClassName),
          ],
        }),
      ],
    })
);

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as Example from "./main";

describe("shadcn Button Group example", () => {
  test("renders the shadcn Button Group example", () => {
    Scene.scene(
      { update: Example.update, view: Example.view },
      Scene.with(Example.init()[0]),
      Scene.expect(Scene.role("group", { name: "Report actions" })).toExist(),
      Scene.expect(Scene.role("button", { name: "Archive Report" })).toExist(),
      Scene.expect(
        Scene.role("button", { name: "Archive Report" })
      ).not.toHaveHandler("click"),
      Scene.expect(Scene.role("button", { name: "Snooze" })).toExist(),
      Scene.expect(Scene.role("button", { name: "Snooze" })).not.toHaveHandler(
        "click"
      )
    );
  });
});
